// Deterministic content generation for the migration fixtures. A tiny
// xorshift PRNG keeps every generated byte reproducible, so the
// committed project.json hashes stay stable across runs.
package main

import (
	"fmt"
	"os"
	"path/filepath"

	"mediarelink/internal/media"
)

type prng struct{ state uint64 }

func newPRNG(seed uint64) *prng {
	if seed == 0 {
		seed = 0x9e3779b97f4a7c15
	}
	return &prng{state: seed}
}

func (p *prng) next() uint64 {
	p.state ^= p.state << 13
	p.state ^= p.state >> 7
	p.state ^= p.state << 17
	return p.state
}

func (p *prng) bytes(n int) []byte {
	out := make([]byte, n)
	for i := range out {
		if i%8 == 0 {
			p.next()
		}
		out[i] = byte(p.state >> ((i % 8) * 8))
	}
	return out
}

// content is one generated media payload.
type content struct {
	codec      string
	durationMS int64
	fpsNum     int
	fpsDen     int
	sampleRate int
	audio      []byte
	frames     [][]byte
}

// makeContent builds deterministic payload bytes from a seed.
func makeContent(seed uint64, codec string, durationMS int64, fpsNum, fpsDen, frameCount int) content {
	rng := newPRNG(seed)
	frames := make([][]byte, frameCount)
	for i := range frames {
		frames[i] = rng.bytes(48)
	}
	return content{
		codec:      codec,
		durationMS: durationMS,
		fpsNum:     fpsNum,
		fpsDen:     fpsDen,
		sampleRate: 48000,
		audio:      rng.bytes(2048),
		frames:     frames,
	}
}

// reencode derives a "re-encoded" variant: same duration, codec and
// audio, but different frame bytes.
func (c content) reencode(seed uint64) content {
	rng := newPRNG(seed)
	out := c
	out.frames = make([][]byte, len(c.frames))
	for i := range out.frames {
		out.frames[i] = rng.bytes(48)
	}
	return out
}

// write encodes the content to path, creating parent directories.
func (c content) write(path string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	if err := media.Encode(path, c.codec, c.durationMS, c.fpsNum, c.fpsDen,
		c.sampleRate, c.audio, c.frames); err != nil {
		return fmt.Errorf("encode %s: %w", path, err)
	}
	return nil
}
